package org.nonfood.oilplants.dao;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.nonfood.oilplants.config.Database;import org.nonfood.oilplants.model.*;import org.nonfood.oilplants.service.PlantService;import java.math.BigDecimal;import java.sql.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="db.integration",matches="true") class PlantCrudIntegrationTest {
 @Test void createsUpdatesSearchesAndDeletesPlantAndSample()throws Exception{
  String suffix=UUID.randomUUID().toString().substring(0,8);long[] ids={0,0,0};PlantDao dao=new PlantDao();
  try{
   try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO plant_families(family_name_zh,family_name_latin) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,"集成测试科"+suffix);p.setString(2,"Integrationaceae"+suffix);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();ids[0]=k.getLong(1);}}
   try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO plant_genera(family_id,genus_name_zh,genus_name_latin) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,ids[0]);p.setString(2,"集成测试属");p.setString(3,"Integrationgenus"+suffix);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();ids[1]=k.getLong(1);}}
   Plant plant=new Plant();plant.setGenusId(ids[1]);plant.setNameZh("集成测试植物"+suffix);plant.setScientificName("Integrationplant "+suffix);plant.setVerificationStatus("NEEDS_REVIEW");OilSample sample=new OilSample();sample.setLabel("initial");sample.setOilContentPct(new BigDecimal("31.250"));sample.setSourcePages("p. 7");FattyAcid acid=new FattyAcid();acid.setName("test acid");acid.setPercentage(new BigDecimal("25.000"));ids[2]=dao.create(plant,sample,List.of(acid));
   assertTrue(dao.findById(ids[2],true).isPresent());PlantSearchCriteria criteria=new PlantSearchCriteria();criteria.setKeyword("集成测试植物"+suffix);assertEquals(1,dao.search(criteria,true).getTotal());
   plant.setId(ids[2]);plant.setNameZh("更新植物"+suffix);dao.update(plant,null,List.of());long sampleId=dao.findById(ids[2],true).orElseThrow().getSamples().get(0).getId();new PlantService(dao).updateSample(ids[2],sampleId,"revised","44.500","p. 8","integration update","revised acid=12.000","VERIFIED","VERIFIED","VERIFIED");
   Plant reloaded=dao.findById(ids[2],true).orElseThrow();assertEquals("更新植物"+suffix,reloaded.getNameZh());assertEquals(new BigDecimal("44.500"),reloaded.getSamples().get(0).getOilContentPct());assertEquals("revised acid",reloaded.getSamples().get(0).getComponents().get(0).getName());assertEquals("VERIFIED",reloaded.getSamples().get(0).getVerificationStatus());assertEquals("VERIFIED",reloaded.getSamples().get(0).getOilContentStatus());assertEquals("VERIFIED",reloaded.getSamples().get(0).getComponents().get(0).getVerificationStatus());
   assertTrue(dao.delete(ids[2]));assertTrue(dao.findById(ids[2],true).isEmpty());
  }finally{try(Connection c=Database.getConnection()){if(ids[2]>0)try(PreparedStatement p=c.prepareStatement("DELETE FROM plants WHERE id=?")){p.setLong(1,ids[2]);p.executeUpdate();}if(ids[1]>0)try(PreparedStatement p=c.prepareStatement("DELETE FROM plant_genera WHERE id=?")){p.setLong(1,ids[1]);p.executeUpdate();}if(ids[0]>0)try(PreparedStatement p=c.prepareStatement("DELETE FROM plant_families WHERE id=?")){p.setLong(1,ids[0]);p.executeUpdate();}}}
 }
}
